import json
T=json.load(open('data/cache/a065244455cfb2221bcda94a.docs.json'))[0]['text']
S,E=260834,268832
c=json.load(open('loop/state/out/read_xiyou_L1_0037.candidate.json'))
def spans(o):
    if isinstance(o,dict):
        if 'quote' in o and 'start' in o and 'end' in o: yield (o['start'],o['end'])
        else:
            for v in o.values(): yield from spans(v)
    elif isinstance(o,list):
        for v in o: yield from spans(v)
m=[]
