    if m and s0<=m[-1][1]: m[-1][1]=max(m[-1][1],e0)
    else: m.append([s0,e0])
print('covered',sum(e-s for s,e in m),'ratio',round(sum(e-s for s,e in m)/(E-S),3))
print('segments>=25',sum(1 for a,b in zip([S]+[e for _,e in m],[s for s,_ in m]+[E]) if b-a>=25))
